function stepsToOne(s: string): number {
  let steps = 0, carry = 0;
  for (let i = s.length - 1; i > 0; i--) {
    const b = (s[i] === "1" ? 1 : 0) + carry;
    if (b === 1) { steps += 2; carry = 1; }
    else steps += 1; // b is 0 or 2: even, just halve
  }
  return steps + carry;
}

